-- DeutschFlow V77 MySQL/MariaDB schema
SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS=0;

CREATE TABLE IF NOT EXISTS admin_users (id CHAR(36) PRIMARY KEY,email VARCHAR(320) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,role VARCHAR(32) NOT NULL DEFAULT 'admin',is_active TINYINT(1) NOT NULL DEFAULT 1,created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS languages (code VARCHAR(10) PRIMARY KEY,name VARCHAR(120) NOT NULL,native_name VARCHAR(120),is_active TINYINT(1) NOT NULL DEFAULT 1,sort_order INT NOT NULL DEFAULT 0,created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS courses (id CHAR(36) PRIMARY KEY,slug VARCHAR(160) NOT NULL UNIQUE,title_json LONGTEXT NOT NULL,description_json LONGTEXT NOT NULL,is_active TINYINT(1) NOT NULL DEFAULT 1,sort_order INT NOT NULL DEFAULT 0,created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS course_levels (id CHAR(36) PRIMARY KEY,course_id CHAR(36) NOT NULL,slug VARCHAR(80) NOT NULL,title_json LONGTEXT NOT NULL,description_json LONGTEXT NOT NULL,is_active TINYINT(1) NOT NULL DEFAULT 1,sort_order INT NOT NULL DEFAULT 0,legacy_id INT,created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),UNIQUE KEY uq_course_level_slug(course_id,slug),CONSTRAINT fk_levels_course FOREIGN KEY(course_id) REFERENCES courses(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS course_categories (id CHAR(36) PRIMARY KEY,course_id CHAR(36) NOT NULL,legacy_id INT,name VARCHAR(255) NOT NULL,icon VARCHAR(255),description TEXT,is_active TINYINT(1) NOT NULL DEFAULT 1,sort_order INT NOT NULL DEFAULT 0,created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),UNIQUE KEY uq_category_legacy(course_id,legacy_id),CONSTRAINT fk_categories_course FOREIGN KEY(course_id) REFERENCES courses(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS course_series (id CHAR(36) PRIMARY KEY,course_id CHAR(36) NOT NULL,legacy_id INT,title VARCHAR(255) NOT NULL,subtitle VARCHAR(255),description TEXT,cover_url TEXT,is_featured TINYINT(1) NOT NULL DEFAULT 0,is_active TINYINT(1) NOT NULL DEFAULT 1,created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),UNIQUE KEY uq_series_legacy(course_id,legacy_id),CONSTRAINT fk_series_course FOREIGN KEY(course_id) REFERENCES courses(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS chapters (id CHAR(36) PRIMARY KEY,level_id CHAR(36) NOT NULL,slug VARCHAR(200) NOT NULL,number INT NOT NULL,title_json LONGTEXT NOT NULL,description_json LONGTEXT NOT NULL,is_active TINYINT(1) NOT NULL DEFAULT 1,sort_order INT NOT NULL DEFAULT 0,legacy_id INT,category_id CHAR(36),series_id CHAR(36),duration_seconds INT NOT NULL DEFAULT 0,is_premium TINYINT(1) NOT NULL DEFAULT 0,is_featured TINYINT(1) NOT NULL DEFAULT 0,transcript_de LONGTEXT,notes_json LONGTEXT NOT NULL,vocabulary_json LONGTEXT,created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),UNIQUE KEY uq_chapter_slug(level_id,slug),CONSTRAINT fk_chapter_level FOREIGN KEY(level_id) REFERENCES course_levels(id) ON DELETE CASCADE,CONSTRAINT fk_chapter_category FOREIGN KEY(category_id) REFERENCES course_categories(id) ON DELETE SET NULL,CONSTRAINT fk_chapter_series FOREIGN KEY(series_id) REFERENCES course_series(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS chapter_translations (id CHAR(36) PRIMARY KEY,chapter_id CHAR(36) NOT NULL,legacy_id INT,language_code VARCHAR(10) NOT NULL,title TEXT,notes LONGTEXT,audio_url TEXT,is_published TINYINT(1) NOT NULL DEFAULT 0,created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),UNIQUE KEY uq_translation_lang(chapter_id,language_code),CONSTRAINT fk_translation_chapter FOREIGN KEY(chapter_id) REFERENCES chapters(id) ON DELETE CASCADE,CONSTRAINT fk_translation_lang FOREIGN KEY(language_code) REFERENCES languages(code)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS chapter_assets (id CHAR(36) PRIMARY KEY,chapter_id CHAR(36) NOT NULL,language_code VARCHAR(10),asset_type VARCHAR(80) NOT NULL,storage_path TEXT NOT NULL,public_url TEXT,duration_seconds INT,size_bytes BIGINT,sha256 VARCHAR(128),version VARCHAR(100) NOT NULL DEFAULT '1',is_active TINYINT(1) NOT NULL DEFAULT 1,created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),CONSTRAINT fk_asset_chapter FOREIGN KEY(chapter_id) REFERENCES chapters(id) ON DELETE CASCADE,CONSTRAINT fk_asset_lang FOREIGN KEY(language_code) REFERENCES languages(code)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS chapter_notes (id CHAR(36) PRIMARY KEY,chapter_id CHAR(36) NOT NULL,legacy_id INT,language_code VARCHAR(10) NOT NULL,content LONGTEXT NOT NULL,created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),UNIQUE KEY uq_note_lang(chapter_id,language_code),CONSTRAINT fk_note_chapter FOREIGN KEY(chapter_id) REFERENCES chapters(id) ON DELETE CASCADE,CONSTRAINT fk_note_lang FOREIGN KEY(language_code) REFERENCES languages(code)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS chapter_transcripts (id CHAR(36) PRIMARY KEY,chapter_id CHAR(36) NOT NULL,legacy_id INT,language_code VARCHAR(10) NOT NULL,content LONGTEXT NOT NULL,sort_order INT NOT NULL DEFAULT 0,created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),UNIQUE KEY uq_transcript_lang_sort(chapter_id,language_code,sort_order),CONSTRAINT fk_transcript_chapter FOREIGN KEY(chapter_id) REFERENCES chapters(id) ON DELETE CASCADE,CONSTRAINT fk_transcript_lang FOREIGN KEY(language_code) REFERENCES languages(code)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS chapter_vocabulary (id CHAR(36) PRIMARY KEY,chapter_id CHAR(36) NOT NULL,legacy_id INT,german TEXT NOT NULL,english TEXT,meaning_json LONGTEXT NOT NULL,sort_order INT NOT NULL DEFAULT 0,created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),CONSTRAINT fk_vocab_chapter FOREIGN KEY(chapter_id) REFERENCES chapters(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS chapter_vocabulary_translations (id CHAR(36) PRIMARY KEY,vocabulary_id CHAR(36) NOT NULL,legacy_id INT,language_code VARCHAR(10) NOT NULL,meaning TEXT,created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),UNIQUE KEY uq_vocab_translation(vocabulary_id,language_code),CONSTRAINT fk_vt_vocab FOREIGN KEY(vocabulary_id) REFERENCES chapter_vocabulary(id) ON DELETE CASCADE,CONSTRAINT fk_vt_lang FOREIGN KEY(language_code) REFERENCES languages(code)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS chapter_videos (id CHAR(36) PRIMARY KEY,chapter_id CHAR(36) NOT NULL,legacy_id INT,title VARCHAR(255) NOT NULL DEFAULT 'Video Overview',video_url TEXT NOT NULL,thumbnail_url TEXT,duration_seconds INT NOT NULL DEFAULT 0,is_enabled TINYINT(1) NOT NULL DEFAULT 1,is_premium TINYINT(1) NOT NULL DEFAULT 1,show_as_preview TINYINT(1) NOT NULL DEFAULT 0,sort_order INT NOT NULL DEFAULT 0,language_code VARCHAR(10),created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),CONSTRAINT fk_video_chapter FOREIGN KEY(chapter_id) REFERENCES chapters(id) ON DELETE CASCADE,CONSTRAINT fk_video_lang FOREIGN KEY(language_code) REFERENCES languages(code)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS chapter_quiz_questions (id CHAR(36) PRIMARY KEY,chapter_id CHAR(36) NOT NULL,legacy_id INT,source_table VARCHAR(120) NOT NULL DEFAULT 'quiz_questions',question LONGTEXT NOT NULL,options_json LONGTEXT NOT NULL,correct_option VARCHAR(30) NOT NULL,explanation LONGTEXT,sort_order INT NOT NULL DEFAULT 0,is_active TINYINT(1) NOT NULL DEFAULT 1,language_code VARCHAR(10),created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),CONSTRAINT fk_quiz_chapter FOREIGN KEY(chapter_id) REFERENCES chapters(id) ON DELETE CASCADE,CONSTRAINT fk_quiz_lang FOREIGN KEY(language_code) REFERENCES languages(code)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS lid_catalogs (id CHAR(36) PRIMARY KEY,version VARCHAR(120) NOT NULL,title VARCHAR(255) NOT NULL,total_cards INT NOT NULL,general_cards INT NOT NULL,state_cards INT NOT NULL,source_storage_path TEXT,source_file_url TEXT,schema_version VARCHAR(30) NOT NULL DEFAULT '2',metadata_json LONGTEXT NOT NULL,is_active TINYINT(1) NOT NULL DEFAULT 1,created_by CHAR(36),created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS lid_cards (id CHAR(36) PRIMARY KEY,catalog_id CHAR(36) NOT NULL,catalog_key VARCHAR(255) NOT NULL,part VARCHAR(20) NOT NULL,state VARCHAR(80),number INT NOT NULL,page INT,question_json LONGTEXT NOT NULL,choices_json LONGTEXT NOT NULL,answer_key VARCHAR(30) NOT NULL,correct_choice_json LONGTEXT NOT NULL,learn_json LONGTEXT NOT NULL,study_material_json LONGTEXT,requires_image TINYINT(1) NOT NULL DEFAULT 0,image_note TEXT,created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),UNIQUE KEY uq_lid_card(catalog_id,catalog_key),CONSTRAINT fk_lid_card_catalog FOREIGN KEY(catalog_id) REFERENCES lid_catalogs(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS lid_assets (id CHAR(36) PRIMARY KEY,catalog_id CHAR(36),asset_type VARCHAR(80) NOT NULL,language_code VARCHAR(10),asset_key VARCHAR(255) NOT NULL,storage_path TEXT NOT NULL,public_url TEXT,size_bytes BIGINT,sha256 VARCHAR(128),version VARCHAR(100) NOT NULL DEFAULT '1',is_active TINYINT(1) NOT NULL DEFAULT 1,created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),CONSTRAINT fk_lid_asset_catalog FOREIGN KEY(catalog_id) REFERENCES lid_catalogs(id) ON DELETE CASCADE,CONSTRAINT fk_lid_asset_lang FOREIGN KEY(language_code) REFERENCES languages(code)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS content_releases (id CHAR(36) PRIMARY KEY,module VARCHAR(80) NOT NULL,version VARCHAR(120) NOT NULL,language_code VARCHAR(10),manifest_json LONGTEXT NOT NULL,manifest_storage_path TEXT,manifest_public_url TEXT,published_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),published_by CHAR(36),is_active TINYINT(1) NOT NULL DEFAULT 1,KEY idx_release(module,language_code,published_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS content_assets (id CHAR(36) PRIMARY KEY,module VARCHAR(80) NOT NULL,asset_key VARCHAR(255) NOT NULL,asset_type VARCHAR(80) NOT NULL,language_code VARCHAR(10),storage_path TEXT NOT NULL,public_url TEXT,size_bytes BIGINT,sha256 VARCHAR(128),version VARCHAR(100) NOT NULL DEFAULT '1',metadata_json LONGTEXT NOT NULL,is_active TINYINT(1) NOT NULL DEFAULT 1,created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS app_config (config_key VARCHAR(255) PRIMARY KEY,value_json LONGTEXT NOT NULL,updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS user_progress (id CHAR(36) PRIMARY KEY,user_id VARCHAR(128) NOT NULL,module VARCHAR(80) NOT NULL,item_key VARCHAR(255) NOT NULL,status VARCHAR(80),score DECIMAL(10,2),payload_json LONGTEXT NOT NULL,updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),UNIQUE KEY uq_progress(user_id,module,item_key)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS lid_attempts (id CHAR(36) PRIMARY KEY,user_id VARCHAR(128),catalog_id CHAR(36),selected_state VARCHAR(80),score INT NOT NULL,total_questions INT NOT NULL DEFAULT 33,passed TINYINT(1) NOT NULL,time_taken_seconds INT,answers_json LONGTEXT NOT NULL,created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),CONSTRAINT fk_attempt_catalog FOREIGN KEY(catalog_id) REFERENCES lid_catalogs(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
SET FOREIGN_KEY_CHECKS=1;
